  1→import { TestBed } from "@angular/core/testing";
  2→import { ExerciseStore } from "./exercise.store";
  3→import { handleStateChange, toActiveDecision } from "./ws-state-handler";
  4→import type { DecisionOpened, PhaseChange, SystemStateChange } from "./generated/state-changes.types";
  5→
  6→describe("ws-state-handler", () => {
  7→  let store: InstanceType<typeof ExerciseStore>;
  8→
  9→  beforeEach(() => {
 10→    TestBed.configureTestingModule({ providers: [ExerciseStore] });
 11→    store = TestBed.inject(ExerciseStore);
 12→  });
 13→
 14→  describe("toActiveDecision", () => {
 15→    it("maps DecisionOpened to ActiveDecision", () => {
 16→      const opened: DecisionOpened = {
 17→        type: "decision_opened",
 18→        id: "d1",
 19→        decision_id: "d1",
 20→        event_id: null,
 21→        issue_id: "i1",
 22→        title: "Fix the bug?",
 23→        description: "Choose wisely",
 24→        question_type: "single_choice",
 25→        options: [{ id: "o1", label: "Yes", score: 10, stress_delta: 0, system_effects: [], targets_system: false, max_plays: 1, role: null }],
 26→        completion_mode: "first_response",
 27→        target_roles: ["advisor"],
 28→        timeout_ms: 30000,
 29→        max_selections: 1,
 30→        status: "open",
 31→        opened_at_pt_ms: 5000,
 32→        closed_at_pt_ms: null,
 33→        recommendations: {},
 34→      };
 35→      const result = toActiveDecision(opened);
 36→      expect(result.id).toBe("d1");
 37→      expect(result.title).toBe("Fix the bug?");
 38→      expect(result.max_selections).toBe(1);
 39→      expect(result.status).toBe("open");
 40→      expect(result.closed_at_pt_ms).toBeNull();
 41→    });
 42→  });
 43→
 44→  describe("handleStateChange", () => {
 45→    it("applies phase_change to store", () => {
 46→      const change: PhaseChange = {
 47→        type: "phase_change",
 48→        action: "started",
 49→        phase: "running",
 50→        time: { play_time_ms: 1000, real_time_ms: 1000, factor: 1, paused: false },
 51→      };
 52→      handleStateChange(change, store);
 53→      expect(store.phase()).toBe("running");
 54→      expect(store.playTimeMs()).toBe(1000);
 55→    });
 56→
 57→    it("appends decision on decision_opened", () => {
 58→      const change: DecisionOpened = {
 59→        type: "decision_opened",
 60→        id: "d1",
 61→        decision_id: "d1",
 62→        event_id: null,
 63→        issue_id: null,
 64→        title: "Test",
 65→        description: "",
 66→        question_type: "single_choice",
 67→        options: [],
 68→        completion_mode: "first_response",
 69→        target_roles: [],
 70→        timeout_ms: 0,
 71→        max_selections: null,
 72→        status: "open",
 73→        opened_at_pt_ms: 0,
 74→        closed_at_pt_ms: null,
 75→        recommendations: {},
 76→      };
 77→      handleStateChange(change, store);
 78→      expect(store.openDecisions().length).toBe(1);
 79→      expect(store.openDecisions()[0].id).toBe("d1");
 80→    });
 81→
 82→    it("closes decision on decision_closed", () => {
 83→      store.applyDecisions([
 84→        { id: "d1", title: "T", status: "open" } as any,
 85→      ]);
 86→      handleStateChange(
 87→        { type: "decision_closed", decision_id: "d1", title: "T", selected_option_ids: [] },
 88→        store,
 89→      );
 90→      expect(store.openDecisions().length).toBe(0);
 91→    });
 92→
 93→    it("dispatches applySystemChange on system_state_change", () => {
 94→      // Seed a system first
 95→      store.applySnapshot({
 96→        exercise_id: 1,
 97→        title: "Test",
 98→        phase: "running",
 99→        time: { play_time_ms: 0, real_time_ms: 0, factor: 1, paused: false },
100→        events: [],
101→        issues: [],
102→        systems: [{ system_id: "nav", label: "NAV", category: "sensor", power: true, operational: "green" }],
103→        score: null,
104→      });
105→      const change: SystemStateChange = {
106→        type: "system_state_change",
107→        system_id: "nav",
108→        action: "power_changed",
109→        power: false,
110→        operational: "green",
111→      };
112→      handleStateChange(change, store);
113→      expect(store.systems()[0].power).toBe(false);
114→    });
115→  });
116→});
