  // Check if Angular's store has decisions
  const el = document.querySelector('tfc-logs-drawer');
  if (!el) return 'no logs-drawer element';
  // Try to access the component's input
  const ng = window.ng;
  if (!ng) return 'no Angular devtools';
  const comp = ng.getComponent(el);
  if (!comp) return 'no component instance';
  const decisions = comp.decisions?.();
  return { decisionsCount: decisions?.length ?? 0, firstDecision: decisions?.[0]?.title ?? null };
}

() => {
  const playerView = document.querySelector('tfc-player-view');
  if (!playerView) return 'no player view';
  const ng = window.ng;
  if (!ng) return 'no ng';
  const comp = ng.getComponent(playerView);
  if (!comp) return 'no component';
  const store = comp.store;
  const decisions = store.decisions();
  const openDecisions = store.openDecisions();
  return {
    totalDecisions: decisions.length,
    openDecisions: openDecisions.length,
    decisionIds: decisions.map(d => d.id),
    decisionStatuses: decisions.map(d => d.status)
  };
}

