    const d = p.getAttribute('d');
    if (d && d.includes('\n')) {
      issues.push({ index: i, parent: p.closest('svg')?.className?.baseVal || 'unknown', snippet: d.substring(0, 100) });
    }
  });
  return { totalPaths: allPaths.length, issuesFound: issues.length, issues };
}

