 12→interface DecisionLogEntry {
 13→  turnNumber: number;
 14→  title: string;
 15→  status: string;
 16→  recommendations: { roleLabel: string; optionLabel: string }[];
 17→  finalDecision: string[] | null;
 18→}
 19→
 20→@Component({
 21→  selector: "tfc-logs-drawer",
 22→  changeDetection: ChangeDetectionStrategy.OnPush,
 23→  imports: [DrawerPanelComponent],
 24→  template: `
 25→    <ui-drawer-panel side="right" [open]="open()" (closed)="open.set(false)">
 26→      <h2 drawerTitle>Decision Log</h2>
 27→      <div class="decision-log">
 28→        @for (entry of decisionLog(); track entry.turnNumber) {
 29→          <div class="decision-entry" [attr.data-status]="entry.status" data-testid="decision-entry">
 30→            <div class="decision-header">
 31→              <span class="decision-turn">Turn {{ entry.turnNumber }}</span>
 32→              <span class="decision-title">{{ entry.title }}</span>
 33→            </div>
 34→            @if (entry.recommendations.length > 0) {
 35→              <div class="decision-recommendations">
 36→                @for (rec of entry.recommendations; track rec.roleLabel) {
 37→                  <div class="decision-rec" data-testid="recommendation">
 38→                    <span class="decision-rec__role">{{ rec.roleLabel }}</span>
 39→                    <span class="decision-rec__arrow">&rarr;</span>
 40→                    <span class="decision-rec__option">{{ rec.optionLabel }}</span>
 41→                  </div>
 42→                }
 43→              </div>
 44→            }
 45→            @if (entry.finalDecision) {
 46→              <div class="decision-final" data-testid="final-decision">
 47→                <span class="decision-final__label">Final</span>
 48→                <span class="decision-final__arrow">&rarr;</span>
 49→                <span class="decision-final__option">{{ entry.finalDecision.join(', ') }}</span>
 50→              </div>
 51→            } @else {
 52→              <div class="decision-pending">Awaiting decision...</div>
 53→            }
 54→          </div>
 55→        } @empty {
 56→          <p class="logs-empty">No decisions yet.</p>
 57→        }
 58→      </div>
 59→    </ui-drawer-panel>
 60→  `,
 61→})
 62→export class LogsDrawerComponent {
 63→  readonly open = model(false);
 64→  readonly decisions = input<ActiveDecision[]>([]);
 65→  readonly roles = input<RoleDef[]>([]);
 66→
 67→  protected decisionLog = computed<DecisionLogEntry[]>(() => {
 68→    const decisions = this.decisions();
 69→    const roles = this.roles();
 70→    const roleMap = new Map(roles.map((r) => [r.id, r.label]));
 71→
 72→    return decisions
 73→      .slice()
 74→      .sort((a, b) => a.opened_at_pt_ms - b.opened_at_pt_ms)
 75→      .map((d, i) => this.toLogEntry(d, i + 1, roleMap));
 76→  });
 77→
 78→  private toLogEntry(
 79→    d: ActiveDecision,
 80→    turnNumber: number,
 81→    roleMap: Map<string, string>,
 82→  ): DecisionLogEntry {
 83→    const optionMap = new Map(
 84→      d.options.map((o) => [o.id, o.label]),
 85→    );
 86→
 87→    const recommendations = Object.entries(d.recommendations).map(
 88→      ([key, optionId]) => {
 89→        const roleId = key.includes(":") ? key.split(":")[1] : key;
 90→        return {
 91→          roleLabel: roleMap.get(roleId) ?? roleId,
 92→          optionLabel: optionMap.get(optionId) ?? optionId,
 93→        };
 94→      },
 95→    );
 96→
 97→    const finalDecision =
 98→      d.status === "closed" && d.selected_option_ids.length > 0
 99→        ? d.selected_option_ids.map((id: string) => optionMap.get(id) ?? id)
100→        : null;
101→
102→    return {
103→      turnNumber,
104→      title: d.title,
105→      status: d.status,
106→      recommendations,
107→      finalDecision,
108→    };
109→  }
110→}
