 54→export class PlayerView implements OnInit, OnDestroy {
 55→  protected readonly store = inject(ExerciseStore);
 56→  protected readonly domain = inject(DomainService);
 57→  private readonly api = inject(EngineApiService);
 58→  private readonly decisionApi = inject(DecisionApiService);
 59→  protected readonly logsOpen = signal(false);
 60→  private readonly ws = inject(ExerciseWsService);
 61→  private readonly router = inject(Router);
 62→  private readonly route = inject(ActivatedRoute);
 63→  protected readonly roleLabel = signal("Advisor");
 64→  protected readonly beginningExercise = signal(false);
 65→  private readonly exerciseId = signal(1);
 66→  private readonly participantId = signal("");
 67→  private readonly tick = inject(TickService);
 68→  private snapshotLoaded = false;
 69→  private sub: Subscription | null = null;
 70→  private connSub: Subscription | null = null;
 71→
 72→  protected readonly activeDecisions = computed(() => {
 73→    const role = this.store.playerRole();
 74→    return this.store.openDecisions().filter((d) => {
 75→      if (!d.target_roles || d.target_roles.length === 0) return true;
 76→      if (role === "all_roles" || role === "all_advisors" || role === "solo_player") return true;
 77→      return d.target_roles.includes(role);
 78→    });
 79→  });
 80→
 81→  protected readonly isMultiRole = computed(() => {
 82→    const role = this.store.playerRole();
 83→    return role === "all_advisors" || role === "solo_player" || role === "all_roles";
 84→  });
 85→
 86→  protected readonly submittedRoles = signal<Set<string>>(new Set());
 87→
 88→  protected readonly currentTurnEvent = computed(() => {
 89→    const decisions = this.activeDecisions();
 90→    if (decisions.length === 0) return null;
 91→    const decision = decisions[0];
 92→    if (!decision.event_id) return null;
 93→    return this.store.events().find((e) => e.id === decision.event_id) ?? null;
 94→  });
 95→
 96→  protected readonly roleCards = computed(() => {
 97→    const allRoles = this.store.context()?.roles ?? [];
 98→    const event = this.currentTurnEvent();
 99→    const decision = this.activeDecisions()[0] ?? null;
100→    const role = this.store.playerRole();
101→    const multiRole = this.isMultiRole();
102→    const showDecisionMaker =
103→      role === "all_roles" || role === "solo_player" || this.store.isPracticeMode();
104→    // Single-role players see only their own role card
105→    const roles = multiRole ? allRoles : allRoles.filter((r) => r.id === role);
106→    return buildRoleCards(roles, event, decision, this.submittedRoles(), showDecisionMaker);
107→  });
108→
109→  private _lastDecisionId: string | null = null;
110→  private readonly resetSubmittedRolesEffect = effect(() => {
111→    const id = this.activeDecisions()[0]?.id ?? null;
112→    // Only reset when the decision ID actually changes (not on every WS push)
113→    if (id && id !== this._lastDecisionId) {
114→      this._lastDecisionId = id;
115→      this.submittedRoles.set(new Set());
116→    }
117→  });
118→
119→  // Turn advancement is backend-driven: closing a decision triggers the
120→  // next event in sequence automatically via engine.force_trigger_next_decision.
121→
122→  ngOnInit(): void {
123→    const params = this.route.snapshot.queryParams;
124→    const id = Number(params["exerciseId"] ?? 1);
125→    const pId = String(params["participantId"] ?? "");
126→    const role = String(params["role"] ?? "player");
127→    const gameMode = String(params["gameMode"] ?? "");
128→    this.exerciseId.set(id);
129→    this.participantId.set(pId);
130→    this.store.setParticipantId(pId);
131→    this.store.setPlayerRole(role);
132→    if (gameMode) {
133→      this.store.setGameMode(gameMode);
134→    }
135→    const practiceMode = params["practiceMode"] === "true";
136→    this.store.setPracticeMode(practiceMode);
137→    this.ws.connect(id, "player", pId || undefined);
138→    this.sub = this.ws.messages$.subscribe((msg) =>
139→      handlePlayerWsMessage(msg, this.store, () => this.onExerciseStopped()),
140→    );
141→    this.loadSnapshot(id);
142→    this.decisionApi.getContext(id).subscribe({
143→      next: (ctx) =>
144→        resolvePlayerRole(ctx, role, gameMode, this.store, this.roleLabel),
145→      error: () => {},
146→    });
147→    this.decisionApi.getEngineDecisions(id).subscribe({
148→      next: (decisions) => this.store.applyDecisions(decisions),
149→      error: () => {},
150→    });
151→    this.connSub = this.ws.connected$.subscribe((connected) => {
152→      if (connected && this.snapshotLoaded) this.loadSnapshot(id);
153→    });
154→    this.tick.start(this.store);
155→  }
156→
157→  private loadSnapshot(exerciseId: number): void {
158→    this.api.snapshot(exerciseId).subscribe({
159→      next: (snap) => {
160→        this.snapshotLoaded = true;
161→        this.store.applySnapshot(snap);
162→      },
163→      error: () => this.store.setError("Failed to load snapshot"),
164→    });
165→  }
166→
167→  protected onBeginExercise(): void {
168→    this.beginningExercise.set(true);
169→    this.api.begin(this.exerciseId()).subscribe({
170→      next: (change) => {
171→        this.store.applyPhaseChange(change.phase);
172→        this.store.applyTimeUpdate(change.time);
173→        this.beginningExercise.set(false);
174→      },
175→      error: () => {
176→        this.store.setError("Failed to begin exercise");
177→        this.beginningExercise.set(false);
178→      },
179→    });
180→  }
181→
182→  protected onStop(): void {
183→    this.api.stop(this.exerciseId()).subscribe({
184→      next: () => this.onExerciseStopped(),
185→    });
186→  }
187→
188→  private onExerciseStopped(): void {
189→    this.ws.disconnect();
190→    this.router.navigate(["/"]);
191→  }
192→
193→  ngOnDestroy(): void {
194→    this.tick.stop();
195→    this.ws.disconnect();
196→    this.sub?.unsubscribe();
197→    this.connSub?.unsubscribe();
198→  }
199→  protected onRoleCardSubmitted(submission: RoleCardSubmission): void {
200→    const decision = this.activeDecisions()[0];
201→    if (!decision) return;
202→    const role = this.store.context()?.roles?.find(
203→      (r) => r.id === submission.roleId,
204→    );
205→    if (role?.player_type === "decision_maker") {
206→      submitDecision(
207→        this.decisionApi,
208→        this.store,
209→        this.exerciseId(),
210→        decision,
211→        submission,
212→      );
213→    } else {
214→      submitRoleRecommendation(
215→        this.decisionApi,
216→        this.exerciseId(),
217→        decision,
218→        this.participantId(),
219→        { roleId: submission.roleId, selectedOptions: submission.selectedOptions, freeText: submission.freeText },
220→      );
221→    }
222→    const updated = new Set(this.submittedRoles());
223→    updated.add(submission.roleId);
224→    this.submittedRoles.set(updated);
225→  }
226→}
