 82→export const ExerciseStore = signalStore(
 83→  withState(initialState),
 84→
 85→  withComputed((store) => ({
 86→    rtClock: computed(() => formatTimeMs(store.realTimeMs())),
 87→    ptClock: computed(() => formatTimeMs(store.playTimeMs())),
 88→    activeEvents: computed(() =>
 89→      store.events().filter((e) => e.lifecycle === "running"),
 90→    ), // active injects
 91→    scheduledEvents: computed(() =>
 92→      store.events().filter((e) => e.lifecycle === "scheduled"),
 93→    ), // scheduled injects
 94→    completedEvents: computed(() =>
 95→      store.events().filter((e) => e.lifecycle === "completed"),
 96→    ), // completed injects
 97→    activeIssues: computed(() =>
 98→      store.issues().filter((i) => i.lifecycle === "active"),
 99→    ), // active defects
100→    /** Remaining ms on the active decision timer (null if no open decision with timeout). */
101→    decisionCountdownMs: computed(() => {
102→      const decision = store
103→        .decisions()
104→        .find((d) => d.status === "open" && d.timeout_ms > 0);
105→      if (!decision) return null;
106→      const factor = store.speedFactor() || 1;
107→      const openedAtRt = decision.opened_at_pt_ms / factor;
108→      const elapsed = store.realTimeMs() - openedAtRt;
109→      return Math.max(0, decision.timeout_ms - elapsed);
110→    }),
111→    /** Countdown clock: decision timer when a decision is open, otherwise time to next event. */
112→    turnCountdownClock: computed(() => {
113→      // Prefer decision countdown when an open decision has a timeout
114→      const decision = store
115→        .decisions()
116→        .find((d) => d.status === "open" && d.timeout_ms > 0);
117→      if (decision) {
118→        const factor = store.speedFactor() || 1;
119→        const openedAtRt = decision.opened_at_pt_ms / factor;
120→        const elapsed = store.realTimeMs() - openedAtRt;
121→        return formatTimeMs(Math.max(0, decision.timeout_ms - elapsed));
122→      }
123→      const pt = store.playTimeMs();
124→      const nextEvent = store
125→        .events()
126→        .filter((e) => e.lifecycle === "scheduled" && e.scheduled_pt_ms > pt)
127→        .sort((a, b) => a.scheduled_pt_ms - b.scheduled_pt_ms)[0];
128→      if (!nextEvent) return null;
129→      const remaining = Math.max(0, nextEvent.scheduled_pt_ms - pt);
130→      return formatTimeMs(remaining);
131→    }),
132→    issuesWithCountdown: computed(() => {
133→      const pt = store.playTimeMs();
134→      return store
135→        .issues()
136→        .filter(
137→          (i) =>
138→            i.lifecycle === "active" &&
139→            i.auto_resolve_ms > 0 &&
140→            i.activated_at_pt_ms !== null,
141→        )
142→        .map((i) => {
143→          const elapsed = pt - (i.activated_at_pt_ms ?? 0);
144→          const remaining = Math.max(0, i.auto_resolve_ms - elapsed);
145→          return { ...i, remaining_ms: remaining };
146→        });
147→    }),
148→    releasedIssues: computed(() => store.issues().filter((i) => i.released)),
149→    openDecisions: computed(() =>
150→      store.decisions().filter((d) => d.status === "open"),
151→    ),
152→    hasOpenDecision: computed(
153→      () => store.decisions().filter((d) => d.status === "open").length > 0,
154→    ),
155→    connectedParticipants: computed(() =>
156→      store.participants().filter((p) => p.connected),
157→    ),
158→    connectedCount: computed(
159→      () => store.participants().filter((p) => p.connected).length,
160→    ),
161→    isCollaborative: computed(
162→      () => store.gameMode() === "simple_collaborative",
163→    ),
164→    isDecisionMaker: computed(() => store.playerType() === "decision_maker"),
165→    isAllAdvisors: computed(() => store.playerRole() === "all_advisors"),
166→    isPracticeMode: computed(() => store.practiceMode()),
167→    phaseBadgeVariant: computed<"default" | "secondary" | "destructive">(() => {
168→      switch (store.phase()) {
169→        case "running":
170→          return "default";
171→        case "paused":
172→          return "secondary";
173→        case "completed":
174→          return "destructive";
175→        default:
176→          return "secondary";
177→      }
178→    }),
179→  })),
180→
181→  withMethods((store) => ({
182→    setExerciseId(id: number): void {
183→      patchState(store, { exerciseId: id });
184→    },
185→
186→    applySnapshot(snapshot: SnapshotWithScore): void {
187→      patchState(store, {
188→        exerciseId: snapshot.exercise_id,
189→        title: snapshot.title,
190→        phase: snapshot.phase,
191→        playTimeMs: snapshot.time.play_time_ms,
192→        realTimeMs: snapshot.time.real_time_ms,
193→        speedFactor: snapshot.time.factor,
194→        paused: snapshot.time.paused,
195→        events: snapshot.events,
196→        issues: snapshot.issues,
197→        systems: snapshot.systems ?? store.systems(),
198→        decisions: snapshot.decisions ?? store.decisions(),
199→        score: snapshot.score
200→          ? {
201→              totalScore: snapshot.score.total_score,
202→              stress: snapshot.score.stress,
203→              turnNumber: snapshot.score.turn_number,
204→              nextDecisionTimeMs: snapshot.score.next_decision_time_ms,
205→            }
206→          : store.score(),
207→        loading: false,
208→        error: null,
209→      });
210→    },
211→
212→    applyTimeUpdate(time: TimeSnapshot): void {
213→      patchState(store, {
214→        playTimeMs: time.play_time_ms,
215→        realTimeMs: time.real_time_ms,
216→        speedFactor: time.factor,
217→        paused: time.paused,
218→      });
219→    },
220→
221→    /** Advance clocks locally by wall-clock delta (call from a setInterval). */
222→    tick(wallDeltaMs: number): void {
223→      if (store.paused()) return;
224→      const factor = store.speedFactor();
225→      patchState(store, {
226→        realTimeMs: store.realTimeMs() + wallDeltaMs,
227→        playTimeMs: store.playTimeMs() + wallDeltaMs * factor,
228→      });
229→    },
230→
231→    applyPhaseChange(phase: string): void {
232→      patchState(store, { phase });
233→    },
234→
235→    updateEvent(eventId: string, lifecycle: string): void {
236→      const events = store
237→        .events()
238→        .map((e) => (e.id === eventId ? { ...e, lifecycle } : e));
239→      patchState(store, { events });
240→    },
241→
242→    updateIssue(issueId: string, lifecycle: string, released?: boolean): void {
243→      const issues = store
244→        .issues()
245→        .map((i) =>
246→          i.id === issueId
247→            ? { ...i, lifecycle, released: released ?? i.released }
248→            : i,
249→        );
250→      patchState(store, { issues });
251→    },
252→
253→    setLoading(loading: boolean): void {
254→      patchState(store, { loading });
255→    },
256→
257→    setError(error: string): void {
258→      patchState(store, { error, loading: false });
259→    },
260→
261→    applyDecisions(decisions: ActiveDecision[]): void {
262→      patchState(store, { decisions });
263→    },
264→
265→    setContext(ctx: ScenarioContext): void {
266→      patchState(store, { context: ctx });
267→    },
268→
269→    setParticipantId(id: string): void {
270→      patchState(store, { participantId: id });
271→    },
272→
273→    setPlayerRole(role: string): void {
274→      patchState(store, { playerRole: role });
275→    },
276→
277→    closeDecision(decisionId: string, selectedOptionIds?: string[]): void {
278→      const decisions = store
279→        .decisions()
280→        .map((d) =>
281→          d.id === decisionId
282→            ? { ...d, status: "closed", selected_option_ids: selectedOptionIds ?? d.selected_option_ids }
283→            : d,
284→        );
285→      patchState(store, { decisions });
286→    },
287→
288→    updatePresence(participants: ParticipantPresence[]): void {
289→      patchState(store, { participants });
290→    },
291→
292→    setGameMode(mode: string): void {
293→      patchState(store, { gameMode: mode });
294→    },
295→
296→    setPracticeMode(practice: boolean): void {
297→      patchState(store, { practiceMode: practice });
298→    },
299→
300→    setPlayerType(playerType: string): void {
301→      patchState(store, { playerType });
302→    },
303→
304→    setSpeedFactor(factor: number): void {
305→      patchState(store, { speedFactor: factor });
306→    },
307→
308→    applyScoreChange(change: Pick<ScoreChange, "total_score" | "stress" | "next_decision_time_ms" | "turn_number">): void {
309→      patchState(store, {
310→        score: {
311→          totalScore: change.total_score,
312→          stress: change.stress,
313→          nextDecisionTimeMs: change.next_decision_time_ms,
314→          turnNumber: change.turn_number,
315→        },
316→      });
317→    },
318→
319→    applyRecommendation(
320→      decisionId: string,
321→      participantId: string,
322→      optionId: string,
323→    ): void {
324→      const decisions = store.decisions().map((d) =>
325→        d.id === decisionId
326→          ? {
327→              ...d,
328→              recommendations: {
329→                ...d.recommendations,
330→                [participantId]: optionId,
331→              },
332→            }
333→          : d,
334→      );
335→      patchState(store, { decisions });
336→    },
337→
338→    applySystemChange(change: Pick<SystemStateChange, "system_id" | "action" | "power" | "operational">): void {
339→      const systems = store.systems().map((s) =>
340→        s.system_id === change.system_id
341→          ? { ...s, power: change.power, operational: change.operational }
342→          : s,
343→      );
344→      patchState(store, { systems });
345→    },
346→  })),
347→);
