 62→const RECONNECT_DELAYS = [1000, 2000, 4000, 8000, 16000];
 63→const PING_INTERVAL = 15000;
 64→
 65→@Injectable({ providedIn: "root" })
 66→export class ExerciseWsService implements OnDestroy {
 67→  private ws: WebSocket | null = null;
 68→  private readonly _messages$ = new Subject<WsMessage>();
 69→  private readonly _connected$ = new Subject<boolean>();
 70→  private intentionalClose = false;
 71→  private reconnectAttempt = 0;
 72→  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
 73→  private pingTimer: ReturnType<typeof setInterval> | null = null;
 74→  private lastExerciseId = 0;
 75→  private lastRole: "gm" | "player" = "player";
 76→  private lastParticipantId?: string;
 77→
 78→  readonly messages$ = this._messages$.asObservable();
 79→  readonly connected$ = this._connected$.asObservable();
 80→
 81→  connect(
 82→    exerciseId: number,
 83→    role: "gm" | "player",
 84→    participantId?: string,
 85→  ): void {
 86→    this.intentionalClose = false;
 87→    this.lastExerciseId = exerciseId;
 88→    this.lastRole = role;
 89→    this.lastParticipantId = participantId;
 90→    this.reconnectAttempt = 0;
 91→    this.doConnect(exerciseId, role, participantId);
 92→  }
 93→
 94→  disconnect(): void {
 95→    this.intentionalClose = true;
 96→    this.clearTimers();
 97→    if (this.ws) {
 98→      this.ws.close();
 99→      this.ws = null;
100→    }
101→  }
102→
103→  ngOnDestroy(): void {
104→    this.disconnect();
105→    this._messages$.complete();
106→    this._connected$.complete();
107→  }
108→
109→  private doConnect(
110→    exerciseId: number,
111→    role: string,
112→    participantId?: string,
113→  ): void {
114→    if (this.ws) {
115→      this.ws.close();
116→      this.ws = null;
117→    }
118→    let url = `${environment.wsBaseUrl}/api/exercises/${exerciseId}/ws?role=${role}`;
119→    if (participantId) {
120→      url += `&participant_id=${encodeURIComponent(participantId)}`;
121→    }
122→    this.ws = new WebSocket(url);
123→
124→    this.ws.onopen = () => {
125→      this._connected$.next(true);
126→      this.startPing();
127→    };
128→
129→    this.ws.onmessage = (event: MessageEvent<string>) => {
130→      try {
131→        const data: WsMessage = JSON.parse(event.data);
132→        this.reconnectAttempt = 0;
133→        this._messages$.next(data);
134→      } catch {
135→        // ignore malformed messages
136→      }
137→    };
138→
139→    this.ws.onclose = () => {
140→      this._connected$.next(false);
141→      this.stopPing();
142→      if (!this.intentionalClose) {
143→        this.scheduleReconnect();
144→      }
145→    };
146→
147→    this.ws.onerror = () => {
148→      this._connected$.next(false);
149→    };
150→  }
