() => {
  const el = document.querySelector('tfc-player-view');
  const ng = window.ng;
  const comp = ng.getComponent(el);
  const store = comp.store;
  const decisions = store.decisions();
  const openD = store.openDecisions();
  const events = store.events();
  const activeD = comp.activeDecisions();
  const currentEvent = comp.currentTurnEvent();
  return {
    totalDecisions: decisions.length,
    openDecisions: openD.map(d => ({ id: d.id, event_id: d.event_id, target_roles: d.target_roles })),
    activeDecisions: activeD.map(d => ({ id: d.id, event_id: d.event_id })),
    currentEvent: currentEvent ? { id: currentEvent.id, title: currentEvent.title } : null,
    evtT2: events.find(e => e.id === 'evt-t2') ? { id: 'evt-t2', title: events.find(e => e.id === 'evt-t2').title, lifecycle: events.find(e => e.id === 'evt-t2').lifecycle } : 'NOT FOUND',
    totalEvents: events.length,
  };
}

() => {
  const el = document.querySelector('tfc-player-view');
  const ng = window.ng;
  const comp = ng.getComponent(el);
  const decisions = comp.store.decisions();
  return decisions.map(d => ({ id: d.id, status: d.status }));
}

