 1→import { Injectable, OnDestroy } from "@angular/core";
 2→import { ExerciseStore } from "./exercise.store";
 3→
 4→/**
 5→ * Drives client-side clock interpolation between server updates.
 6→ * Call `start(store)` once the store is available; the service
 7→ * advances realTimeMs / playTimeMs every second via `store.tick()`.
 8→ */
 9→@Injectable()
10→export class TickService implements OnDestroy {
11→  private timer: ReturnType<typeof setInterval> | null = null;
12→  private lastTime = 0;
13→
14→  start(store: InstanceType<typeof ExerciseStore>): void {
15→    this.stop();
16→    this.lastTime = performance.now();
17→    this.timer = setInterval(() => {
18→      const now = performance.now();
19→      const delta = now - this.lastTime;
20→      this.lastTime = now;
21→      store.tick(delta);
22→    }, 1000);
23→  }
24→
25→  stop(): void {
26→    if (this.timer) {
27→      clearInterval(this.timer);
28→      this.timer = null;
29→    }
30→  }
31→
32→  ngOnDestroy(): void {
33→    this.stop();
34→  }
35→}
